import json
f='exp_data/datasets/tokenized/rw_v2_fasttext_openhermes_vs_rw_v2_bigram_0.1_arcade100k.json'
data=json.load(open(f))
def walk(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f'[{i}]')
    elif isinstance(o,str) and 'hf_REDACTED-TB21-SANITIZE-GIT-REPO-FIXTURE' in o:
        print(path,':',o)
walk(data)
